import { L, info, mc, tf, fill, fillc, type, order, match } from '../_h.js';

export default {
  'cv-basics': [
    L('Images are numbers',
      info('A grid of pixels', 'A digital image is a grid of **pixels**. In a greyscale image each pixel is one number, usually 0 (black) to 255 (white).\n\nA colour image has three numbers per pixel: **red, green, blue**. So an image is an array of shape `(height, width, 3)`.'),
      type('A colour image is 100 pixels high and 200 wide. How many numbers does it contain?', ['60000', '60,000'], '100 × 200 × 3.'),
      mc('In an 8-bit greyscale image, what does 255 represent?', ['White', 'Black', 'Mid-grey', 'Transparent'], '0 is black.'),
      mc('What shape does `cv2.imread` return for a colour image?', ['(height, width, 3)', '(3, height, width)', '(width, height)', '(height × width,)'], 'Height first, channels last, and in BGR order.'),
      match('Match the operation', [['Resize', 'Change the number of pixels'], ['Crop', 'Keep a rectangular region'], ['Greyscale', 'Reduce three channels to one'], ['Normalise', 'Rescale pixel values, for example to 0..1']]),
      mc('OpenCV stores colour channels in which order?', ['BGR', 'RGB', 'GRB', 'HSV'], 'Convert before feeding a model trained on RGB.'),
      fillc('rgb = cv2.cvtColor(img, cv2.COLOR_BGR2___)', ['RGB', 'BGR', 'XYZ', 'RGBA2'], 'A forgotten conversion silently hurts accuracy.'),
      tf('Dividing pixel values by 255 scales them to the range 0 to 1.', true, 'Networks train better on small, consistent input ranges.')),

    L('Filters and convolution',
      info('Sliding a small window', 'A **convolution** slides a small grid of numbers, the **kernel**, over the image. At each position it multiplies the kernel by the pixels beneath and adds the results.\n\nDifferent kernels detect different things: blur, edges, corners.'),
      type('A 3×3 patch is all 2s and the kernel is all 1s. What is the output value?', ['18'], '9 × 2.'),
      match('Match the kernel to its effect', [['All values 1/9', 'Blur'], ['Sobel X', 'Vertical edges'], ['Sobel Y', 'Horizontal edges'], ['Centre 5, neighbours -1', 'Sharpen']]),
      mc('An edge-detection kernel gives output near zero on…', ['A flat region of uniform colour', 'A sharp boundary', 'A corner', 'A line'], 'Its values sum to zero, so no change means no response.'),
      info('Output size', 'For input width `n`, kernel `k`, stride `s`, padding `p`:\n\n```\nout = (n + 2p - k) // s + 1\n```\n\n**Stride** is the step between positions. **Padding** adds a border so the output does not shrink.'),
      type('Input 32, kernel 3, stride 1, padding 0. Output width?', ['30'], '(32 - 3) / 1 + 1.'),
      type('Input 32, kernel 3, stride 1, padding 1. Output width?', ['32'], 'Padding 1 with a 3×3 kernel keeps the size.'),
      type('Input 224, kernel 7, stride 2, padding 3. Output width?', ['112'], '(224 + 6 - 7) // 2 + 1.')),

    L('Convolutional networks',
      info('Learning the kernels', 'In a **CNN** the kernels are not designed by hand: they are **learned**. Early layers learn edges, middle layers textures and parts, deep layers whole objects.\n\nA layer has many kernels; each produces one **feature map**.'),
      mc('Why does a CNN need far fewer weights than a fully connected network on images?', ['The same small kernel is reused at every position', 'It uses smaller images', 'It has no biases', 'It skips training'], 'Weight sharing.'),
      type('A conv layer has 16 kernels of size 3×3 on a 3-channel input. How many weights, ignoring biases?', ['432'], '3 × 3 × 3 × 16.'),
      mc('What does max pooling do?', ['Keeps the largest value in each small region, shrinking the map', 'Adds padding', 'Learns new kernels', 'Normalises colours'], 'It reduces size and adds a little tolerance to shifts.'),
      order('A classic CNN classifier', ['Convolution + ReLU', 'Pooling', 'More convolution + ReLU blocks', 'Flatten or global average pooling', 'Fully connected layer with softmax'], 'Features first, classification at the end.'),
      mc('The receptive field of a neuron is…', ['The region of the input image that can influence it', 'Its number of weights', 'Its output value', 'The batch size'], 'It grows with depth, stride and pooling.'),
      match('Match the architecture to its idea', [['ResNet', 'Skip connections'], ['MobileNet', 'Depthwise separable convolutions'], ['U-Net', 'Encoder-decoder with skips, for segmentation'], ['Vision Transformer', 'Image patches as tokens']]),
      tf('Residual (skip) connections made very deep networks trainable.', true, 'They let gradients bypass layers.')),

    L('Training vision models: interview level',
      info('Borrow, augment, check', '- **Transfer learning:** start from weights pre-trained on a large dataset.\n- **Augmentation:** random flips, crops, colour changes multiply your data.\n- **Same preprocessing** in training and deployment.'),
      mc('You have 800 labelled images of car damage. Best start?', ['Fine-tune a pre-trained network', 'Train a deep network from scratch', 'Use k-means', 'Label nothing'], 'Pre-trained features transfer well.'),
      mc('Which augmentation is unsafe for recognising the digits 6 and 9?', ['Rotating by 180 degrees', 'A small brightness change', 'A small crop', 'Slight blur'], 'It turns one class into the other. Augmentations must keep the label valid.'),
      mc('Validation accuracy is high, but accuracy in the field is poor. Most likely?', ['The field images differ from the training images (domain shift)', 'The GPU is slow', 'Too many epochs only', 'The optimiser'], 'Lighting, camera, weather, viewpoint.'),
      mc('Images of the same car appear in both training and test sets. Problem?', ['Leakage: the test score is too optimistic', 'None', 'Underfitting', 'Slow training'], 'Split by car, not by image.'),
      order('Order a strong answer to "Describe a CV project end to end"', ['The problem and constraints', 'Data collection, labelling and splits', 'Model choice and why', 'Metric, baseline and results', 'Deployment constraints and what you would improve'], 'Bring numbers.'),
      mc('Grad-CAM is used to…', ['Show which image regions drove a prediction', 'Speed up training', 'Label data', 'Compress the model'], 'Useful for spotting a model that looks at the wrong thing.'),
      mc('To cut inference time on an embedded target with the least code change, first try…', ['A smaller input resolution and quantisation', 'More layers', 'Float64 weights', 'A larger batch'], 'Then a lighter architecture.'),
      tf('Class imbalance in a detection dataset can be addressed with loss weighting or resampling.', true, 'Focal loss is a common choice.')),

    L('Parameters, receptive fields and normalisation',
      info('Counting parameters', 'A convolution layer has `k × k × C_in × C_out` weights plus `C_out` biases.\n\nA **1×1 convolution** has k = 1: it mixes the channels at each pixel and is the cheap, standard way to change the number of channels.\n\n**Batch normalisation** rescales activations using the mean and variance of each mini-batch. It steadies training and allows larger learning rates.'),
      type('A 3×3 convolution takes 64 channels in and gives 128 channels out. How many parameters, including the 128 biases?', ['73856', '73,856'], '3 × 3 × 64 × 128 = 73,728, plus 128 biases.'),
      mc('What is a 1×1 convolution mostly used for?', ['Mixing channels and changing their number at each pixel', 'Detecting large edges', 'Blurring the image', 'Increasing the image width'], 'It has no spatial extent, so it only recombines channels.'),
      info('Receptive field and dilation', 'Each extra 3×3, stride-1 layer adds 2 pixels to the receptive field: one layer sees 3×3, two see 5×5, three see 7×7.\n\nA **dilated** convolution spaces the kernel taps apart. A 3×3 kernel with dilation 2 covers a 5×5 area using the same 9 weights.'),
      type('Four stacked 3×3 convolutions with stride 1. What width does the receptive field reach?', ['9'], 'Start at 1 and add 2 per layer: 1 + 4 × 2.'),
      mc('What is the main benefit of batch normalisation?', ['It steadies activations so deep networks train faster and tolerate higher learning rates', 'It removes the need for labels', 'It halves the image size', 'It converts BGR to RGB'], 'It keeps layer inputs in a stable range.'),
      tf('Max pooling has learnable weights.', false, 'It simply takes the maximum, so there is nothing to learn.'),
      type('A depthwise separable convolution maps 32 channels to 64 with a 3×3 kernel. How many weights in total (depthwise plus 1×1 pointwise)?', ['2336', '2,336'], '3 × 3 × 32 = 288, plus 1 × 1 × 32 × 64 = 2,048.'),
      fill('A dilated convolution enlarges the receptive field without adding ___.', ['weights', 'colour channels', 'training images', 'output classes'], 'The same nine weights simply cover a wider area.')),

    L('Common mistakes and debugging',
      info('Silent bugs', 'Vision code rarely crashes when it is wrong. It just gives worse results. The usual suspects:\n\n- **Colour order:** OpenCV is BGR, most models expect RGB.\n- **Data type:** `uint8` arithmetic wraps around instead of saturating.\n- **Size order:** OpenCV uses (width, height); NumPy uses (height, width).\n- **Layout:** PyTorch expects (N, C, H, W).'),
      type('A `uint8` NumPy pixel holds 200. You add 100 with `img + 100`. What value is stored? (Values wrap around at 256.)', ['44'], '300 − 256 = 44, so a bright pixel becomes dark.'),
      mc('You want an image 480 pixels high and 640 wide. What is wrong with this call?', ['`cv2.resize` takes (width, height), so this gives 640 high and 480 wide', 'Nothing, it is correct', 'The interpolation is missing, so it fails', 'It only accepts square sizes'], 'Pass (640, 480) to get 480 rows and 640 columns.', 'small = cv2.resize(img, (480, 640))'),
      mc('The model expects (N, C, H, W). What is missing before the forward pass?', ['Moving channels first, for example `x.permute(2, 0, 1)`, and converting to float', 'Nothing, the shape is fine', 'Converting the image to greyscale', 'Doubling the image size'], 'A NumPy image is (H, W, C).', 'x = torch.from_numpy(img)  # shape (224, 224, 3)\nlogits = model(x.unsqueeze(0))'),
      tf('Forgetting `model.eval()` at test time leaves dropout and batch normalisation in training mode.', true, 'Predictions become noisy and depend on the batch.'),
      info('Training bugs', 'Before tuning anything, check that the pipeline can learn at all.\n\n- At the start, a classifier with C balanced classes should have a loss near `ln(C)`.\n- A healthy model can **overfit one small batch** to near-zero loss. If it cannot, there is a bug in the data, labels or code.\n- Draw a few augmented training images with their labels before every long run.'),
      type('A 10-class classifier starts with random weights. About what cross-entropy loss do you expect at step 0? (Two decimals.)', ['2.30', '2.3', '2.303'], 'ln 10 is about 2.30. A very different value hints at a bug.'),
      mc('Training loss reaches 0.01 while validation loss keeps rising. What now?', ['Add augmentation, regularisation or data: the model is overfitting', 'Train for many more epochs', 'Delete the validation set', 'Raise the learning rate tenfold'], 'The model memorises the training set.'),
      order('Order the steps for a model that will not learn', ['Draw some training images with their labels to check the data', 'Try to overfit a single small batch', 'Check shapes, channel order and normalisation in the pipeline', 'Verify the loss starts near ln(C)', 'Only then tune the learning rate and architecture'], 'Cheap checks first, tuning last.')),

    L('Case study: finding defects on a production line',
      info('The scenario', 'A factory makes metal brackets at 30 per minute. One in 200 has a surface defect. A camera above the belt photographs each part, and a model must flag the bad ones.\n\nYou have 4,000 labelled photographs, but only **20 show a defect**. Walk through the decisions a real team has to make.'),
      mc('Your first model reports 99.5% accuracy. What should worry you?', ['A model that always says "good" would score the same, so accuracy hides the problem', 'Nothing, 99.5% is excellent', 'The images are too large', 'The model is too small'], 'With rare defects, accuracy is almost meaningless.'),
      type('Out of 4,000 images, 20 are defective. What accuracy (as a percentage) does a model that always answers "good" get?', ['99.5', '99.5%'], '3,980 of 4,000 are correct.'),
      mc('You only have 20 defect images. What is the sensible plan?', ['Fine-tune a pre-trained network, add careful augmentation and keep collecting defects', 'Train a large network from scratch', 'Delete the defect images', 'Collect only good parts'], 'Pre-trained features cope with small data.'),
      info('Choosing the operating point', 'A missed defect costs about 50 units (a returned product). A false alarm costs about 1 unit (a re-inspection). Because misses cost far more, you accept more false alarms.\n\nSo you **lower the confidence threshold** and choose it on validation data by total cost, not by accuracy.'),
      mc('Given those costs, how should you set the threshold?', ['Low enough to catch nearly every defect, accepting extra false alarms', 'High, to avoid every false alarm', 'At exactly 0.5 always', 'Random'], 'A miss is 50 times more expensive than a false alarm.'),
      type('On 1,000 test parts, 5 are defective. The model flags 8 parts, and 4 of them are truly defective. What is the recall? (Decimal.)', ['0.8', '80%', '4/5', '.8'], '4 of the 5 real defects were found.'),
      mc('A month later, accuracy drops after the lighting was changed. What is the best long-term fix?', ['Fix the lighting in an enclosure and monitor image statistics and error rates', 'Retrain every hour', 'Ignore it', 'Remove the camera'], 'Controlled lighting is the cheapest accuracy gain in inspection.'),
      order('Order a safe rollout', ['Label data and train a baseline', 'Choose the threshold from the cost of misses and false alarms', 'Run in shadow mode next to human inspectors', 'Switch on automatic rejection for confident cases', 'Monitor and feed corrected cases back into training'], 'Prove it quietly before it acts.'),
      tf('Running the model in shadow mode, without letting it reject parts, is a safe way to measure it on real traffic.', true, 'You gain evidence without risk.')),

    L('Interview drill: CNNs and training',
      info('How interviewers probe', 'The first question is usually simple. The follow-ups change a constraint: less data, less time, a different device.\n\nA strong answer gives a **claim**, the **reason**, a **number or example**, and a **trade-off**. Say what you would measure.'),
      type('A fully connected first layer would take a 224 × 224 colour image as a flat vector. How many inputs is that?', ['150528', '150,528'], '224 × 224 × 3. With 1,000 units that is over 150 million weights, which is why convolutions win.'),
      match('Match the interview question to what it really tests', [['Why not use a fully connected network?', 'Weight sharing and locality'], ['What if you had only 500 images?', 'Transfer learning and augmentation'], ['The model is 98% accurate. Is that good?', 'Class balance and the right metric'], ['How would you ship it?', 'Latency, memory and quantisation']]),
      mc('"What is the weakness of your project?" Which answer is strongest?', ['A real limitation, how you measured it and what you would do about it', '"There is none"', 'A weakness that is really a strength', 'Blaming the data without evidence'], 'Honest, specific and constructive.'),
      info('Making the answer land', 'Open with the answer, then support it. Give one concrete number. If you do not know, say so and describe how you would find out. That earns more trust than bluffing.'),
      order('Order a strong answer to "How do you know your model works in production?"', ['Define the metric that matches the business goal', 'Keep a held-out set that looks like field data', 'Break results down by slice, such as lighting and class', 'Monitor live inputs and outcomes for drift', 'Describe how failures return to the training set'], 'Offline test, slices, monitoring, feedback.'),
      mc('Your new model is 2% better on the test set. How do you decide whether to trust that?', ['Check the test set size and repeat with several seeds to see if the gap exceeds the noise', 'Always trust it', 'Ignore it', 'Retrain until it looks better'], 'Small gaps on small sets are often noise.'),
      tf('It is acceptable in an interview to say you do not know and then explain how you would test it.', true, 'A clear plan shows sound engineering judgement.'))
  ],

  'cv-detection': [
    L('Boxes and overlap',
      info('Classification, detection, segmentation', '**Classification:** what is in the image? One label.\n\n**Detection:** what and **where**? A box and a label for every object.\n\n**Segmentation:** which **pixels** belong to each class or object?'),
      match('Match the task to its output', [['Classification', 'One label for the image'], ['Detection', 'Boxes with labels and scores'], ['Semantic segmentation', 'A class for every pixel'], ['Instance segmentation', 'A separate mask for each object']]),
      info('Describing a box', 'A box is four numbers. Two common formats:\n\n- **Corners:** `[x1, y1, x2, y2]`\n- **Centre:** `[cx, cy, width, height]`\n\nMixing them up is a classic bug.'),
      type('A box is [10, 20, 50, 60] in corner format. What is its area?', ['1600'], '(50 - 10) × (60 - 20).'),
      info('Intersection over union', 'How well does a predicted box match the true one?\n\n```\nIoU = area of overlap / area of union\n```\n\n1 is a perfect match, 0 is no overlap. A detection usually counts as correct when IoU ≥ 0.5.'),
      type('Two identical boxes. What is their IoU?', ['1', '1.0'], 'Overlap equals union.'),
      type('Overlap area is 20 and the two boxes have areas 40 and 60. What is the IoU?', ['0.25', '.25', '1/4'], '20 / (40 + 60 - 20).'),
      fillc('union = area_a + area_b - ___', ['inter', 'area_a', 'iou', '1'], 'The overlap would otherwise be counted twice.')),

    L('How detectors work',
      info('One stage or two', '**Two-stage** (Faster R-CNN): first propose regions that may contain objects, then classify and refine each. Accurate, slower.\n\n**One-stage** (YOLO, SSD): predict boxes and classes directly in a single pass. Fast enough for real time.'),
      mc('Which family is the usual choice for real-time video?', ['One-stage, such as YOLO', 'Two-stage, such as Faster R-CNN', 'k-means', 'A language model'], 'One forward pass per frame.'),
      match('Match the part of a modern detector', [['Backbone', 'Extracts features from the image'], ['Neck', 'Combines features at several scales'], ['Head', 'Predicts boxes, scores and classes'], ['NMS', 'Removes duplicate boxes']]),
      mc('Why use feature maps at several scales?', ['To detect both small and large objects', 'To save memory', 'To remove colour', 'To avoid training'], 'Small objects need high-resolution features.'),
      info('Non-maximum suppression', 'A detector fires many overlapping boxes for one object. **NMS** cleans up:\n\n1. Take the highest-scoring box, keep it.\n2. Delete boxes that overlap it too much (IoU above a threshold).\n3. Repeat with what remains.'),
      order('Order the NMS algorithm', ['Sort boxes by score, highest first', 'Keep the top box', 'Remove boxes whose IoU with it exceeds the threshold', 'Repeat with the remaining boxes'], 'Greedy, by score.'),
      mc('Two people stand close together and one is missed after NMS. Why?', ['Their boxes overlap so much that one was suppressed', 'The image is too bright', 'The backbone is too deep', 'NMS adds boxes'], 'Crowded scenes are a known weakness; raise the threshold or use soft-NMS.'),
      mc('Raising the confidence threshold of a detector…', ['Increases precision and lowers recall', 'Increases both', 'Lowers both', 'Changes nothing'], 'Fewer, more certain detections.')),

    L('Measuring detectors and segmentation',
      info('mAP', 'For one class, sweep the confidence threshold and plot **precision** against **recall**. The area under that curve is **average precision (AP)**.\n\n**mAP** is the mean over classes. "mAP@0.5" uses IoU 0.5 to decide a match; "mAP@0.5:0.95" averages over stricter thresholds.'),
      mc('mAP@0.5 counts a detection as correct when…', ['Its IoU with a same-class ground-truth box is at least 0.5', 'Its score is above 0.5', 'Half the image is covered', 'Recall is 0.5'], 'IoU threshold, not confidence.'),
      mc('A model has high mAP@0.5 but low mAP@0.5:0.95. Meaning?', ['It finds objects, but its boxes are not tight', 'It misses most objects', 'It is too slow', 'It has too many classes'], 'Localisation is loose.'),
      mc('Two predicted boxes match the same ground-truth object. How are they scored?', ['One true positive, one false positive', 'Two true positives', 'Two false positives', 'Ignored'], 'Duplicates are penalised, which is why NMS matters.'),
      info('Segmentation', '**U-Net** is the classic segmentation network: an **encoder** shrinks the image to capture context, a **decoder** enlarges it again, and **skip connections** carry fine detail across.\n\nMetrics: **IoU** per class and the **Dice** coefficient.'),
      mc('What do the skip connections in U-Net provide?', ['Fine spatial detail for sharp boundaries', 'Extra labels', 'A lower learning rate', 'Colour correction'], 'The decoder alone would produce blurry masks.'),
      type('A predicted mask has 30 pixels, the true mask 30, and they share 20. What is the Dice score, as a fraction?', ['2/3', '0.67', '0.667', '0.66'], '2 × 20 / (30 + 30).'),
      mc('Why is pixel accuracy misleading for a small object on a large background?', ['Predicting "background" everywhere already scores very high', 'Pixels cannot be counted', 'It ignores the background', 'It is always 50%'], 'Use IoU or Dice.')),

    L('Detection in the real world: interview level',
      info('What goes wrong', 'Typical failure modes: **small** or distant objects, **occlusion**, **rare classes**, **label noise**, and **domain shift** (night, rain, a new camera).\n\nMost improvements come from **data**: targeted collection, cleaner labels, the right augmentation.'),
      mc('The detector misses small, distant objects. Reasonable first step?', ['Higher input resolution or tiling, and checking small-object labels', 'A lower learning rate', 'Fewer epochs', 'Remove augmentation'], 'Small objects vanish when the image is downscaled.'),
      mc('Your labels have many missing boxes. Effect on training?', ['The model is punished for correct detections and learns to miss objects', 'None', 'It trains faster', 'mAP rises'], 'Label quality sets the ceiling.'),
      mc('The model works by day and fails at night. Best response?', ['Collect and label night data; add suitable augmentation', 'Raise the threshold', 'Add layers', 'Train longer on day data'], 'Cover the conditions you deploy in.'),
      order('Order a strong answer to "Improve this detector"', ['Break the metric down by class, size and condition', 'Inspect failure cases by eye', 'Fix data: labels, coverage, balance', 'Then tune the model and input size', 'Re-evaluate on a held-out field set'], 'Error analysis before architecture.'),
      mc('In-cabin monitoring must run on a small embedded chip. Sensible choice?', ['A small YOLO or MobileNet-based model, quantised', 'The largest available detector', 'A cloud API per frame', 'No model'], 'Meet the frame rate and memory budget first.'),
      mc('Tracking objects across frames adds what to detection?', ['A consistent identity over time', 'More classes', 'Higher resolution', 'Colour'], 'Detect, associate, then update each track.'),
      mc('Anchor-free detectors predict…', ['Box locations directly from points, without preset anchor shapes', 'No boxes', 'Only classes', 'Only masks'], 'Recent YOLO versions are anchor-free.'),
      tf('Evaluating by slice (night, rain, small objects) can reveal problems hidden in an overall mAP.', true, 'Averages hide weak spots.')),

    L('Grids, loss functions and decoding',
      info('Grids and box losses', 'A one-stage detector predicts on a **grid** of cells. A feature map with stride `s` over an image of side `n` has `n / s` cells per side, and each cell predicts boxes.\n\nThe box loss should reward overlap. A plain IoU loss gives **zero gradient** when two boxes do not touch, so variants such as **GIoU** and **CIoU** add a term based on the distance between the boxes.'),
      type('A 640 × 640 image goes through a head with stride 8. How many grid cells does that feature map have in total?', ['6400', '6,400'], '640 / 8 = 80 cells per side, and 80 × 80 = 6,400.'),
      tf('In a one-stage detector, the vast majority of predictions are background.', true, 'Most cells contain no object, which creates a heavy imbalance.'),
      info('Imbalance and focal loss', 'With thousands of background cells for every object, easy background examples swamp the loss. **Focal loss** multiplies each example’s loss by a factor that shrinks when the model is already confident, so training focuses on the hard cases.'),
      mc('What is focal loss designed to do?', ['Down-weight easy examples so rare, hard ones dominate learning', 'Speed up inference', 'Remove the need for NMS', 'Convert boxes to masks'], 'It tackles background-versus-object imbalance.'),
      mc('Why is GIoU preferred over plain IoU as a training loss?', ['Plain IoU gives no learning signal when the boxes do not overlap', 'GIoU runs faster', 'IoU cannot be computed for rectangles', 'GIoU needs no labels'], 'GIoU still produces a gradient for disjoint boxes.'),
      type('Box A is [0, 0, 4, 4] and box B is [2, 0, 6, 4]. What is the IoU, as a fraction?', ['1/3', '0.33', '0.333', '.33'], 'Intersection 2 × 4 = 8, union 16 + 16 − 8 = 24.'),
      type('A detector outputs 50 boxes, 40 of them true positives. The image set contains 80 real objects. What is the recall?', ['0.5', '1/2', '50%', '.5'], '40 of 80 objects were found. The precision would be 40/50 = 0.8.'),
      order('Order the steps for decoding raw detector output', ['Take the raw network output', 'Drop predictions below the confidence threshold', 'Convert box values to corner format', 'Apply non-maximum suppression', 'Rescale the boxes to the original image size'], 'Filter, convert, deduplicate, then map back.')),

    L('Common mistakes and debugging',
      info('Format and coordinate bugs', 'Many "model" problems are really coordinate bugs:\n\n- Mixing `[x1, y1, x2, y2]` with `[cx, cy, w, h]`.\n- Normalised labels (0 to 1) used as if they were pixels.\n- Boxes predicted on a resized or letterboxed image but never mapped back to the original.\n\nAlways draw boxes on an image to check.'),
      mc('A box is [cx, cy, w, h] = [100, 100, 40, 20]. What are its corner coordinates [x1, y1, x2, y2]?', ['[80, 90, 120, 110]', '[100, 100, 140, 120]', '[60, 80, 140, 120]', '[90, 80, 110, 120]'], 'Half the width (20) either side of x, half the height (10) either side of y.'),
      type('A label line says the normalised box width is 0.25, on an image 640 pixels wide. How wide is the box in pixels?', ['160'], '0.25 × 640.'),
      mc('This IoU function sometimes reports 1.0 for boxes that are far apart. Why?', ['It never clamps negative width and height, so two negatives multiply into a positive area', 'It divides by zero', 'Boxes cannot be far apart', 'It uses integer division'], 'For [0,0,2,2] and [4,4,6,6] the width and height are both −2, giving an area of 4.', 'def iou(a, b):\n    w = min(a[2], b[2]) - max(a[0], b[0])\n    h = min(a[3], b[3]) - max(a[1], b[1])\n    inter = w * h\n    return inter / (area(a) + area(b) - inter)'),
      tf('If an image was letterboxed to 640 × 640 before inference, predicted boxes must be mapped back to the original image coordinates.', true, 'Otherwise they are shifted and scaled wrongly.'),
      info('Evaluation bugs', 'Metrics can be wrong without any error message.\n\n- Compute mAP with a **very low** confidence threshold (about 0.001) so the whole precision-recall curve exists.\n- NMS is normally done **per class**. Class-agnostic NMS can delete a person standing beside a bicycle.\n- Split by video or location, not by frame, or near-duplicate frames leak into the test set.'),
      mc('You compute mAP after keeping only detections with confidence at least 0.5. What happens?', ['The precision-recall curve is cut short, so the mAP is lower than it should be', 'The mAP is exact', 'The mAP becomes 1', 'Nothing changes'], 'Low-confidence detections extend the recall range.'),
      mc('A person and a bicycle overlap heavily and one box disappears after NMS. What setting is the likely cause?', ['NMS was applied across all classes instead of per class', 'The image is too bright', 'The backbone is too deep', 'The batch size is too small'], 'Boxes of different classes should not suppress each other.'),
      order('Order the checks for a detector whose mAP is close to zero', ['Draw the ground-truth boxes on some training images', 'Draw the predictions on the same images', 'Check box format, scale and class-id mapping', 'Try to overfit ten images', 'Scale up to the full dataset']  , 'Look at the data before changing the model.')),

    L('Case study: counting free parking bays',
      info('The scenario', 'A car park has 40 cameras. Every minute the system must report how many bays are free so that a sign can guide drivers. Each camera gives 1920 × 1080 frames, and cars appear about 90 pixels wide.\n\nA team can reuse existing cameras, so the choices are about **modelling**, **evaluation** and **reliability**.'),
      mc('Which design is the sensible first choice?', ['Detect vehicles, then test each bay area for overlap with a detected box', 'Segment the sky', 'Train a speech model', 'Classify the whole frame as full or empty'], 'Detection gives locations; bays are fixed polygons you can mark once per camera.'),
      type('The frame is resized from 1920 pixels wide to 640. A car 90 pixels wide becomes how many pixels wide?', ['30'], '90 × 640 / 1920. Small objects like this get lost, so consider tiling or higher resolution.'),
      mc('A car only 30 pixels wide is often missed. Which change helps most?', ['Run on tiles or at a higher resolution so cars stay large', 'Reduce the resolution further', 'Remove the small cars from the labels', 'Lower the learning rate'], 'Do not throw away the pixels the object needs.'),
      info('Deciding if a bay is occupied', 'For each bay, compute what fraction of its area is covered by a detected car box. Call the bay occupied above a threshold, for example **40%**. Using bay coverage rather than box IoU suits this job, because a car is bigger than its bay and IoU would be low.'),
      tf('A bay that is 30% covered by a car box, with a 40% threshold, is counted as free.', true, '30% is below the threshold.'),
      mc('Which measure best tells the car park operator whether the system works?', ['Error in the free-bay count per camera, split by day, night and rain', 'Training loss', 'The size of the model file', 'mAP alone on a public dataset'], 'Evaluate the number people actually see, by condition.'),
      mc('The displayed count flickers up and down because a car is missed in one frame out of five. What helps?', ['Smooth over several frames, for example a median of the last five counts', 'Raise the resolution only', 'Show every raw frame result', 'Remove the sign'], 'A bay does not change state every few seconds.'),
      order('Order the rollout', ['Pilot on two cameras', 'Label about 500 frames across day, night and weather', 'Fine-tune a small pre-trained detector', 'Evaluate the bay-count error per condition', 'Add temporal smoothing, roll out and monitor'], 'Pilot first, then scale with monitoring.')),

    L('Interview drill: detection',
      info('Questions you will get', 'Detection interviews tend to cover three areas: **how it works** (anchors, NMS, one-stage versus two-stage), **how you measure it** (IoU, precision, recall, mAP) and **what you do when it fails**. Expect the interviewer to add a constraint after your first answer.'),
      type('A detector makes 40 predictions and 30 are correct. What is its precision, as a decimal?', ['0.75', '.75', '3/4', '75%'], '30 / 40.'),
      match('Match the interview question to what it really tests', [['Why not just use a classifier?', 'Knowing detection answers where as well as what'], ['What does NMS do and when does it fail?', 'Duplicates and crowded scenes'], ['Is mAP enough to ship?', 'Slices, latency and failure review'], ['Your recall is low. What now?', 'Error analysis before architecture changes']]),
      mc('"YOLO or Faster R-CNN?" What is the strongest opening?', ['Ask about latency, hardware and object size, then justify the choice', 'Always say YOLO', 'Always say Faster R-CNN', 'Say it does not matter'], 'The right model depends on the constraints.'),
      mc('Follow-up: NMS removes a true detection in a crowd. A good answer is…', ['Use soft-NMS, which lowers scores instead of deleting boxes, or tune the threshold', 'Turn NMS off and accept duplicates forever', 'Remove crowds from the data', 'Use fewer classes'], 'Soft-NMS decays overlapping scores rather than discarding them.'),
      info('A structure for evaluation answers', 'When asked how you evaluate, move from definition to decision: define a match, trace precision against recall, summarise, break down by slice, then add cost and speed.'),
      order('Order a strong answer to "How do you evaluate a detector?"', ['Define a match: IoU above a threshold with a same-class ground truth box', 'Trace precision and recall across confidence thresholds', 'Summarise as average precision per class and the mean', 'Break results down by object size and condition', 'Add latency and a review of failure cases'], 'Definition, curve, summary, slices, cost.'),
      mc('mAP rose by one point, but the new model is 40% slower. Do you ship it?', ['It depends on the latency budget and on whether the gain holds on the slices that matter', 'Yes, accuracy always wins', 'No, speed never matters', 'Only if the file is smaller'], 'State the trade-off and ask what the product needs.'),
      tf('Asking clarifying questions about constraints before choosing a model is a strength in an interview.', true, 'It shows you design for requirements rather than fashion.'))
  ],

  'cv-geometry': [
    L('How a camera sees',
      info('The pinhole model', 'Light from a 3-D point passes through a tiny hole and lands on the sensor. Far objects appear smaller.\n\nFor a point `(X, Y, Z)` in front of the camera:\n\n```\nu = f · X / Z + cx\nv = f · Y / Z + cy\n```\n\n`f` is the focal length in pixels; `(cx, cy)` is the image centre.'),
      type('f = 1000, cx = 500. A point at X = 1, Z = 10. What is u?', ['600'], '1000 × 1 / 10 + 500.'),
      mc('The same object moves twice as far away. Its size in the image…', ['Halves', 'Doubles', 'Stays the same', 'Becomes zero'], 'Image size is proportional to 1 / Z.'),
      mc('What information is lost when a 3-D scene becomes a 2-D image?', ['Depth', 'Colour', 'Brightness', 'Edges'], 'Every point along a ray lands on the same pixel.'),
      match('Match the parameter', [['Focal length', 'How strongly the lens magnifies'], ['Principal point', 'Where the optical axis meets the image'], ['Intrinsics', 'Properties of the camera itself'], ['Extrinsics', 'Where the camera is and where it points']]),
      mc('A longer focal length gives…', ['A narrower field of view and more magnification', 'A wider field of view', 'More depth of colour', 'No change'], 'Telephoto against wide-angle.'),
      tf('A point behind the camera (Z ≤ 0) cannot be projected into the image.', true, 'Always check Z before dividing.'),
      mc('Estimating distance from a single camera uses…', ['Known object size and focal length', 'The colour of the object', 'The frame rate', 'The file size'], 'distance = f × real height / pixel height.')),

    L('Distortion and calibration',
      info('Real lenses bend lines', 'The pinhole model assumes straight lines stay straight. Real lenses, especially wide ones, bend them: **distortion**.\n\n**Fisheye** lenses see about 180° and distort strongly. They need their own model.'),
      mc('Straight building edges look curved near the image border. This is…', ['Lens distortion', 'Motion blur', 'Noise', 'Compression'], 'Radial distortion grows toward the edges.'),
      mc('Why do surround-view systems use fisheye cameras?', ['Four cameras can cover 360° around the vehicle', 'They are distortion-free', 'They need no calibration', 'They are cheaper to label'], 'The price is heavy distortion.'),
      info('Calibration', 'To find a camera’s parameters, photograph a known pattern (a **checkerboard**) from many angles. Software detects the corners and solves for:\n\n- **intrinsics** and **distortion coefficients**\n- **extrinsics:** the camera’s pose'),
      order('Order a camera calibration', ['Print or display a checkerboard of known size', 'Capture it at many positions and angles', 'Detect the corner points', 'Solve for intrinsics and distortion', 'Check the reprojection error'], 'Cover the whole image, including the corners.'),
      mc('What is the reprojection error?', ['The distance between detected points and where the model says they should be', 'The time the calibration takes', 'The number of images', 'The lens price'], 'Well under one pixel is good.'),
      mc('The camera on a vehicle is slightly rotated after a repair. Which calibration changed?', ['Extrinsic', 'Intrinsic', 'Colour', 'None'], 'Its pose relative to the vehicle.'),
      tf('A small extrinsic error can cause visible misalignment in a stitched surround view.', true, 'One degree is large at a distance.')),

    L('Homography and stitching',
      info('Mapping one view onto another', 'A **homography** is a 3×3 matrix that maps points between two images of the same **plane** (such as the ground).\n\n```\n[x\', y\', w] = H · [x, y, 1],   then divide by w\n```\n\nIt has 8 degrees of freedom, so **4 point pairs** define it.'),
      type('How many point correspondences are needed, at minimum, to compute a homography?', ['4', 'four'], 'Each pair gives two equations; there are 8 unknowns.'),
      mc('A homography exactly relates two images when…', ['The scene is flat, or the camera only rotates', 'Always', 'The images are the same size', 'The cameras are identical'], 'Otherwise depth differences cause parallax.'),
      info('Parallax', 'Hold a finger up and close one eye, then the other: the finger jumps against the background. That is **parallax**.\n\nTwo cameras at different positions see near objects shift more than far ones. One homography cannot fix that, so stitched images show **ghosting**.'),
      mc('In a bird’s-eye view, the ground looks right but a nearby pole appears twice. Cause?', ['Parallax: the pole is not on the ground plane', 'Wrong colour space', 'Low resolution', 'Too much blur'], 'The mapping is only valid for the plane it was computed for.'),
      order('Order a feature-based stitching pipeline', ['Detect keypoints and descriptors', 'Match them between images', 'Estimate the homography with RANSAC', 'Warp one image onto the other', 'Blend the seam'], 'RANSAC rejects wrong matches.'),
      mc('What is RANSAC for?', ['Fitting a model while ignoring outlier matches', 'Sharpening', 'Colour balance', 'Detecting corners'], 'Fit to random minimal sets, keep the model with most inliers.'),
      mc('In a vehicle surround view, the mapping between cameras comes mainly from…', ['Offline calibration of fixed cameras', 'Live feature matching every frame', 'Guessing', 'The radio'], 'The cameras do not move relative to the car.')),

    L('Learned stitching and interview level',
      info('Where networks help', 'Geometry gives a stable global alignment but cannot remove parallax.\n\n- A network can predict a **flexible warp** (a mesh or flow field), trained without labels by making the overlapping regions agree.\n- A segmentation-style network (**U-Net**) can learn the **seam and blending mask**.'),
      mc('Why can deep stitching be trained without labelled data?', ['The loss compares the warped overlap regions with each other', 'It needs no loss', 'Labels are generated by hand in secret', 'It memorises the test set'], 'Unsupervised: the images supervise themselves.'),
      mc('What is the strength of a hybrid (geometry plus network) pipeline?', ['Calibrated geometry is stable; the network refines local misalignment', 'It needs no calibration', 'It is always slower', 'It removes cameras'], 'Each part does what it is good at.'),
      mc('A stitching network runs at 8 fps and you need 30. First options?', ['Lower resolution for the network, a lighter backbone, quantisation', 'More layers', 'A bigger image', 'Remove calibration'], 'Often the warp can be predicted at low resolution and applied at full resolution.'),
      match('Match the artefact to its cause', [['Ghosting', 'Parallax or misalignment'], ['Visible seam', 'Exposure or colour difference'], ['Bent lines', 'Uncorrected distortion or a bad warp'], ['Flicker', 'Frame-to-frame inconsistency']]),
      mc('Stitched video flickers although each frame looks fine. Fix?', ['Add temporal smoothing or a consistency constraint', 'Raise the resolution', 'Use more cameras', 'Disable blending'], 'Per-frame estimates jitter.'),
      order('Order a strong answer to "Explain your stitching pipeline"', ['Calibrate and undistort each camera', 'Project to a common surface using extrinsics', 'Refine local alignment, for example with a learned warp', 'Choose the seam and blend', 'Meet the real-time budget on the target'], 'Geometry, refinement, appearance, performance.'),
      mc('How would you measure stitching quality without ground truth?', ['Similarity in the overlap region and human rating of artefacts', 'Classification accuracy', 'mAP', 'Word error rate'], 'For example PSNR or SSIM in the overlap, plus visual review.'),
      tf('The pinhole model alone is adequate for a 180° fisheye lens.', false, 'It needs a fisheye projection model.')),

    L('Intrinsics, extrinsics and field of view',
      info('The camera matrix', 'The intrinsics fit in one matrix:\n\n```\nK = [[f, 0, cx],\n     [0, f, cy],\n     [0, 0,  1]]\n```\n\nThe focal length in **pixels** is `f_px = f_mm × image_width_px / sensor_width_mm`.\n\nThe extrinsics move a world point into camera coordinates: `Xc = R · Xw + t`. Only then do you project with `K`.'),
      type('A lens has f = 4 mm, the sensor is 6.4 mm wide and the image is 1280 pixels wide. What is the focal length in pixels?', ['800'], '4 × 1280 / 6.4.'),
      mc('Which step comes first when projecting a world point into an image?', ['Transform it into camera coordinates with the extrinsics', 'Apply the intrinsics, then the extrinsics', 'Divide by the image width', 'Convert to greyscale'], 'Intrinsics only make sense in the camera’s own frame.'),
      type('A world point is (1, 0, 5). The camera has R = identity and t = (0, 0, −2), so Xc = Xw + t. With f = 600 and cx = 320, what is u?', ['520'], 'Xc = (1, 0, 3), so u = 600 × 1 / 3 + 320.'),
      info('Field of view', 'The horizontal field of view depends on the image width `W` and the focal length in pixels:\n\n```\nFOV = 2 · atan(W / (2f))\n```\n\nA longer focal length gives a narrower view.'),
      type('An image is 1280 pixels wide and f = 640 pixels. What is the horizontal field of view in degrees?', ['90'], '2 × atan(1) = 2 × 45°.'),
      tf('The homographies H and 2H map every point to the same place.', true, 'The scale cancels when you divide by w.'),
      mc('Why use more than four point pairs when estimating a homography?', ['Extra points average out measurement noise, and RANSAC can reject bad ones', 'Four pairs are mathematically impossible', 'More points make the matrix larger', 'It removes the need for calibration'], 'Four is the minimum, not the best.'),
      mc('To build a bird’s-eye view, why do systems usually map each output pixel back into the source image?', ['It guarantees every output pixel gets a value, with no holes', 'It needs no calibration', 'It is the only way to blend', 'It removes distortion automatically'], 'Forward mapping leaves gaps between pixels.')),

    L('Common mistakes and debugging',
      info('Geometry bugs are quiet', 'A wrong calibration or a wrong sign rarely raises an error. You just see bent lines, shifted objects or a seam that never quite lines up. Typical causes: points behind the camera, distortion corrected twice, mixing up camera position and translation, and a calibration that does not cover the whole image.'),
      type('A buggy projection does not check the sign of Z. With f = 500, cx = 0 and a point X = 1, Z = −5, what u does it return?', ['-100', '−100'], '500 × 1 / (−5). The mirrored point appears in front of the camera, so reject Z ≤ 0.'),
      mc('Straight lines now bend the opposite way after you undistorted images that were already corrected by the camera’s own processing. What happened?', ['Distortion was corrected twice', 'The images are too bright', 'The resolution is too low', 'RANSAC failed'], 'Check whether the stream is already rectified.'),
      mc('In `Xc = R · Xw + t`, what is the translation t?', ['Not the camera position: it equals −R · C, where C is the camera centre', 'Exactly the camera position', 'The focal length', 'The image centre'], 'This sign and frame confusion is a classic bug.'),
      tf('Changing the focus of a lens can slightly change its intrinsic parameters.', true, 'Calibrate at the focus setting you deploy.'),
      info('Stitching bugs', 'In feature-based stitching, check the **inlier ratio** after RANSAC: a low ratio means the matches or the model are poor. The reprojection threshold passed to `findHomography` is in pixels. Too large lets bad matches in; too small throws away good ones.'),
      mc('What does the 5.0 mean in this call?', ['The reprojection threshold in pixels: matches further off than this are outliers', 'The number of matches', 'The blend width', 'The focal length'], 'It decides who counts as an inlier.', 'H, mask = cv2.findHomography(src, dst, cv2.RANSAC, 5.0)'),
      mc('The ground lines up perfectly in a stitched view, but a nearby bollard appears twice. Is this a calibration bug?', ['Probably not: it is parallax, because the bollard is off the ground plane', 'Yes, recalibrate the focal length', 'Yes, increase the resolution', 'It is a colour bug'], 'If the ground is aligned, the plane model works.'),
      mc('After warping, half the panorama is missing. What is the most likely cause?', ['Some warped points have negative coordinates and the output canvas offset was not added', 'The images are too sharp', 'The homography has too few points', 'The lens is too long'], 'Shift the canvas so all warped points fall inside it.'),
      order('Order the checks for a misaligned stitch', ['Confirm each undistorted image has straight lines', 'Check the reprojection error of the calibration', 'Check the inlier ratio of the matches', 'Inspect the overlap region directly', 'Only then adjust the blending'], 'Fix geometry before appearance.')),

    L('Case study: a surround-view system for parking',
      info('The scenario', 'A car has four fisheye cameras, each with a 190° view and 1280 × 800 pixels. The driver should see a top-down picture of the car and its surroundings at 30 frames per second, to help with parking. You decide how the system is built.'),
      mc('What is the right order of calibration?', ['Intrinsics with a fisheye model for each camera, then extrinsics at the end of the production line', 'Skip calibration and match features live', 'Extrinsics only', 'Calibrate once for all cars with no checks'], 'Each camera and each mounting differs slightly.'),
      type('The top-down canvas covers 10 m × 10 m at 100 pixels per metre. How many output pixels must be produced per second at 30 frames per second?', ['30000000', '30,000,000'], '1000 × 1000 = 1,000,000 pixels per frame, times 30.'),
      mc('Why can the pixel mapping be computed once, as a lookup table, instead of every frame?', ['The cameras are fixed to the car, so the geometry does not change from frame to frame', 'The scene never changes', 'Lookup tables remove distortion for free', 'Frames are always identical'], 'Each frame just reads the table, which is fast on embedded hardware.'),
      info('Why tall objects stretch', 'The top-down view assumes every pixel lies **on the ground**. A point above the ground is projected along its viewing ray until that ray hits the ground, so it lands too far away.\n\nFor a camera at height `H`, a point at height `h` and horizontal distance `d` lands at `d × H / (H − h)`.'),
      tf('In a ground-plane bird’s-eye view, a vertical pole appears stretched away from the camera.', true, 'Its upper parts are projected much farther out.'),
      type('A camera is 1.0 m high. The top of a post is 0.5 m high and 2 m away horizontally. At what distance on the ground does it appear in the top-down view, in metres?', ['4'], '2 × 1.0 / (1.0 − 0.5).'),
      mc('After a repair, the rear camera’s seam no longer lines up. What do you do?', ['Recalibrate that camera’s extrinsics and ideally detect such drift automatically', 'Retrain the lens', 'Change the output resolution', 'Increase the frame rate'], 'The camera’s pose has changed.'),
      order('Order the pipeline', ['Calibrate each camera and build the lookup tables', 'Undistort and project each frame onto the ground plane', 'Apply exposure and gain compensation across cameras', 'Blend the overlap regions', 'Draw the car model and guide lines on top'], 'Geometry, then appearance, then the interface.')),

    L('Interview drill: geometry and stitching',
      info('Questions you will get', 'Geometry interviews check whether you can connect **maths to a picture**. Expect: what a homography needs, why stitched images ghost, how you check calibration, and how a rotation error shows up. Sketch the setup, then give a number.'),
      match('Match the interview question to what it really tests', [['Why does the bird’s-eye view stretch tall objects?', 'The ground-plane assumption'], ['How do you know the calibration is good?', 'Reprojection error and independent checks'], ['Why use RANSAC?', 'Robustness to outlier matches'], ['Why fisheye lenses on a car?', 'Field of view against distortion']]),
      type('A camera has f = 640 pixels. A 1° rotation error moves a point near the image centre by about how many pixels? (Nearest whole number.)', ['11', '11.2', '11.17'], '640 × tan(1°) is about 11.2. Small angles matter a lot.'),
      mc('"Why not match features live every frame in a vehicle?" A strong answer is…', ['The cameras are fixed, so offline calibration is faster and more stable; live matching can fail at night or on blank surfaces', 'Features are illegal in cars', 'Matching is always more accurate', 'Cameras move freely'], 'Use the known geometry.'),
      mc('"How would you notice that a camera has moved after delivery?" A good answer…', ['Monitor drift, for example straight lines or ground features against the stored calibration, and flag recalibration', 'Wait for customers to complain', 'Retrain the network daily', 'Ignore small shifts'], 'Detect it rather than hope.'),
      info('Answer shape', 'Give the principle, the formula or picture, a number, and the limit. For example: "A homography maps a plane. It has 8 degrees of freedom, so 4 correspondences. It fails off the plane because of parallax."'),
      order('Order a strong answer to "How would you debug visible ghosting?"', ['Check whether the ground is aligned, which separates calibration from parallax', 'Verify intrinsics and extrinsics with the reprojection error', 'Inspect the overlap region frame by frame', 'Consider a learned or local warp for off-plane objects', 'Re-evaluate with overlap similarity and visual review'], 'Isolate the cause, then choose the fix.'),
      mc('A colleague says a neural network removes the need for calibration. Your reply?', ['Calibration gives stable global geometry; a network refines local errors and does not replace it', 'Agreed, calibrate nothing', 'Networks cannot handle images', 'Calibration is only for fisheye lenses'], 'Hybrid pipelines combine both.'),
      tf('A learned stitching model removes the need for any camera calibration.', false, 'It still depends on stable geometry, and calibration remains the reliable baseline.'))
  ],

  nlp: [
    L('Text to numbers',
      info('Counting words', 'Models need numbers. The oldest trick: **bag of words**. Build a vocabulary, then represent each document by how many times each word occurs.\n\nSimple and fast, but it ignores order: "dog bites man" and "man bites dog" look identical.'),
      type('Vocabulary: [cat, dog, sat]. What is the bag-of-words vector for "cat sat cat"? Write [a, b, c].', ['[2, 0, 1]', '[2,0,1]', '2, 0, 1', '2,0,1'], 'cat twice, dog never, sat once.'),
      mc('What does bag of words lose?', ['Word order', 'Word counts', 'The vocabulary', 'The document length'], 'Hence "bag".'),
      match('Match the preprocessing step', [['Tokenisation', 'Split text into units'], ['Lowercasing', 'Treat "Cat" and "cat" alike'], ['Stop-word removal', 'Drop very common words'], ['Stemming', 'Reduce words to a root form']]),
      info('TF-IDF', 'Common words such as "the" appear everywhere and tell us little. **TF-IDF** weights a word by:\n\n- **TF:** how often it appears in this document\n- **IDF:** how rare it is across all documents\n\nRare, frequent-here words score highest.'),
      mc('A word appears in every document. Its IDF is…', ['Zero (or very low)', 'Very high', 'Negative infinity', 'One always'], 'ln(N / N) = 0.'),
      mc('Which word gets the highest TF-IDF in an article about radar?', ['"doppler", frequent here and rare elsewhere', '"the"', '"and"', 'A word that never appears'], 'Distinctive terms.'),
      tf('TF-IDF with logistic regression is still a strong baseline for text classification.', true, 'Fast, cheap and explainable.')),

    L('Meaning and context',
      info('Dense vectors', 'Bag of words treats "good" and "great" as unrelated. **Word embeddings** (word2vec, GloVe) give each word a dense vector so that similar words are close.\n\nThey are learned from the idea that words in similar contexts have similar meanings.'),
      mc('In embedding space, which pair is closest?', ['"car" and "vehicle"', '"car" and "banana"', '"car" and "seven"', '"car" and "quickly"'], 'Similar meaning, similar contexts.'),
      mc('A limit of classic word embeddings?', ['One vector per word, whatever the context', 'They are too small', 'They cannot be trained', 'They ignore meaning'], '"bank" gets the same vector in every sentence.'),
      info('Contextual models', '**BERT** and its relatives read the whole sentence and produce a different vector for each word **in its context**. "bank" by a river differs from "bank" with money.\n\n**Sentence embeddings** give one vector for a whole passage, used for search and clustering.'),
      match('Match the generation', [['Bag of words / TF-IDF', 'Sparse counts'], ['word2vec / GloVe', 'One dense vector per word'], ['BERT', 'Context-dependent vectors'], ['Sentence embeddings', 'One vector per passage']]),
      mc('Sub-word tokenisation helps most with…', ['Rare and unseen words', 'Removing punctuation', 'Counting sentences', 'Sorting documents'], 'They are assembled from known pieces.'),
      mc('Which task is BERT-style (encoder) modelling best suited to?', ['Classifying or tagging text', 'Writing long stories', 'Generating code from scratch', 'Speech synthesis'], 'Understanding tasks. Generation suits decoders.'),
      tf('Named-entity recognition labels each token, for example as a person, place or organisation.', true, 'A token-classification task.')),

    L('Measuring generated text',
      info('Overlap metrics', 'How do you score a machine-written summary? Compare it with a human **reference**.\n\n- **BLEU:** share of the output’s n-grams found in the reference (precision). From translation.\n- **ROUGE:** share of the reference’s n-grams found in the output (recall). For summarisation.'),
      type('Reference: "the cat sat on the mat" (6 words). Summary: "the cat sat" (3 words, all present). What is unigram recall, as a fraction?', ['1/2', '0.5', '.5', '3/6'], '3 of the 6 reference words are covered.'),
      mc('ROUGE-L is based on the…', ['Longest common subsequence', 'Number of characters', 'Sentence count', 'Embedding distance'], 'Words in the same order, not necessarily adjacent.'),
      type('Longest common subsequence length of "a b c d" and "a c d"?', ['3'], 'a, c, d appear in order in both.'),
      mc('A summary rewrites the reference in different words and is correct. Its ROUGE will be…', ['Low, although the summary is good', 'High', 'Exactly 1', 'Undefined'], 'Overlap metrics punish paraphrase.'),
      mc('What should complement ROUGE?', ['Human review or a judge model checking faithfulness', 'Nothing', 'Only BLEU', 'Training loss'], 'A fluent summary can still contain invented facts.'),
      match('Match the metric to its task', [['BLEU', 'Translation'], ['ROUGE', 'Summarisation'], ['Word error rate', 'Speech recognition'], ['Exact match / F1', 'Question answering']]),
      tf('A high ROUGE score guarantees that a summary is factually correct.', false, 'It only measures word overlap.')),

    L('Fine-tuning and interview level',
      info('Adapting a language model', 'To specialise a pre-trained model, for example for summarisation:\n\n1. Choose a suitable base model (such as FLAN-T5).\n2. Format data with a consistent **instruction template**.\n3. Fine-tune with **LoRA / PEFT**: train small adapters, keep the base frozen.\n4. Evaluate against the untuned model.'),
      order('Order a LoRA fine-tuning project', ['Pick a pre-trained base model', 'Prepare and tokenise data with a prompt template', 'Attach LoRA adapters and freeze the base', 'Train with a low learning rate and early stopping', 'Evaluate against the base model on held-out data'], 'Always compare with the starting point.'),
      mc('Why is LoRA cheap?', ['It trains a tiny fraction of the parameters', 'It uses no data', 'It skips evaluation', 'It runs on a CPU only'], 'Often well under 1%.'),
      mc('Inputs longer than the model’s limit are…', ['Truncated or split, which you must handle deliberately', 'Processed normally', 'Rejected by the tokenizer always', 'Shortened without loss'], 'Decide what to cut, or chunk and combine.'),
      mc('The fine-tuned model scores the same as the base model. First checks?', ['The prompt template matches between training and inference, and the adapter is actually loaded', 'The GPU colour', 'The file name', 'The batch size only'], 'Template mismatch is a common silent failure.'),
      mc('A challenge specific to Arabic NLP?', ['Rich morphology, optional diacritics and many dialects', 'It has no written form', 'It cannot be tokenised', 'There are no models'], 'Models trained on Modern Standard Arabic often weaken on Egyptian dialect.'),
      order('Order a strong answer to "Build a text classifier with little labelled data"', ['Try a zero-shot or few-shot LLM prompt', 'With some labels, use embeddings plus a simple classifier', 'With more, fine-tune a small pre-trained model', 'Grow labels by correcting uncertain cases', 'Keep a clean human-labelled test set'], 'Escalate with the data you have.'),
      mc('Translating between Arabic and English with an LLM in production, what must you evaluate?', ['Accuracy on domain terms, numbers and names, with human spot checks', 'Only speed', 'Only cost', 'Nothing'], 'Terminology and digits are where errors hurt.'),
      tf('You should hold out a test set that the fine-tuning process never sees.', true, 'Otherwise you cannot trust the improvement.')),

    L('Similarity and attention',
      info('Comparing vectors', 'The **dot product** of two vectors multiplies matching entries and adds them. **Cosine similarity** divides the dot product by the product of the vector lengths:\n\n```\ncos(a, b) = (a · b) / (|a| · |b|)\n```\n\nIt measures the **angle** between vectors: 1 means the same direction, 0 means unrelated, and it ignores length.'),
      type('What is the dot product of [1, 2, 3] and [4, 5, 6]?', ['32'], '4 + 10 + 18.'),
      type('What is the cosine similarity of [1, 0] and [1, 1]? (Two decimals.)', ['0.71', '0.707', '0.7071', '.71'], '1 / (1 × √2) is about 0.707.'),
      mc('Why is cosine similarity often preferred to Euclidean distance for text embeddings?', ['Direction carries the meaning, while vector length can vary with text length or frequency', 'It is always faster', 'It works only for words', 'It needs labels'], 'Length is mostly a nuisance.'),
      info('Attention in one paragraph', 'In a transformer, each token builds a **weighted average** of all tokens’ values. The weights come from `softmax(Q·Kᵀ / √d)`: how well this token’s query matches every key.\n\nA **causal mask** stops decoder tokens seeing later tokens, so they can generate text one token at a time.'),
      mc('Why are attention scores divided by √d?', ['To keep them from growing too large, which would make the softmax saturate', 'To make the vocabulary smaller', 'To remove padding', 'To speed up tokenisation'], 'Large dot products produce near one-hot weights and tiny gradients.'),
      type('A token gives four keys exactly the same score. After softmax, what weight does each get, as a decimal?', ['0.25', '.25', '1/4'], 'Equal scores give equal weights that sum to 1.'),
      mc('How does byte-pair encoding (BPE) build its vocabulary?', ['It repeatedly merges the most frequent adjacent pair of symbols', 'It lists every word in a dictionary', 'It trains a classifier', 'It sorts words alphabetically'], 'Frequent pieces become single tokens.'),
      match('Match the term to its job', [['Causal mask', 'Stops a token seeing later tokens'], ['Positional encoding', 'Tells the model the word order'], ['Softmax', 'Turns scores into weights that sum to 1'], ['Layer normalisation', 'Stabilises activations for each token']])),

    L('Common mistakes and debugging',
      info('Data bugs', 'Most text-model failures start in the data:\n\n- **Leakage:** fitting a vectoriser on all the data before splitting.\n- **Duplicates:** the same or nearly the same text in train and test.\n- **Truncation:** cutting off the part of the text that matters.\n- **Mismatch:** a different tokeniser or template at inference time.'),
      mc('What is the leakage problem in this code?', ['The vocabulary and IDF values were learned using the test documents too', 'The slice is too short', 'The vectoriser is too slow', 'There is no problem'], 'Fit on the training split only, then transform the test split.', 'vec = TfidfVectorizer()\nX = vec.fit_transform(texts)\nX_train, X_test = X[:800], X[800:]'),
      mc('Test accuracy is 99%, but many customer messages are copied between train and test. What do you do?', ['Remove near-duplicates across splits and re-measure', 'Celebrate the result', 'Add more layers', 'Lower the learning rate'], 'Duplicates inflate the score.'),
      tf('Padding tokens should be hidden from attention with an attention mask.', true, 'Otherwise the model attends to meaningless filler.'),
      mc('Reviews end with the verdict, but your pipeline keeps only the first 128 tokens. What is a better choice?', ['Keep the head and the tail, or split the text into chunks and combine the results', 'Keep only the first 128 anyway', 'Delete long reviews silently', 'Use a smaller vocabulary'], 'Truncation should be a decision, not an accident.'),
      info('Training and evaluation bugs', 'Check these before blaming the model:\n\n- Accuracy on **imbalanced** data is misleading, so look at precision and recall per class.\n- The **same tokeniser and prompt template** must be used in training and inference.\n- A fluent summary can still contain **invented facts**, so measure faithfulness.'),
      type('95% of emails are not spam. A classifier always predicts "not spam". What accuracy (as a percentage) does it get?', ['95', '95%'], 'It is right on all 95 not-spam emails, and its recall on spam is 0.'),
      mc('A fine-tuned model outputs nonsense, although training loss looked normal. What do you check first?', ['That inference uses the same tokeniser and prompt template as training', 'The colour of the GPU', 'The name of the file', 'The number of epochs only'], 'Mismatches are a classic silent failure.'),
      mc('Your summariser has excellent ROUGE but quotes a price that is not in the source. What is missing?', ['A faithfulness check, by humans or a judge model, against the source', 'More epochs', 'A larger vocabulary', 'A lower ROUGE threshold'], 'Overlap with a reference does not guarantee truth.'),
      order('Order the debugging steps for a text model that underperforms', ['Check that the loss falls on a tiny batch', 'Decode a few training examples to see what the model really receives', 'Confirm the same tokeniser and template are used at inference', 'Compare against a TF-IDF baseline', 'Only then tune hyperparameters'], 'Verify the pipeline before tuning.')),

    L('Case study: routing support tickets',
      info('The scenario', 'A company receives 20,000 support tickets a month and six queues exist, such as billing and technical. Agents spend about 2 minutes routing each ticket. You have **1,500 labelled tickets**. The goal is to cut routing time without sending customers to the wrong team.'),
      mc('What should you build first?', ['A TF-IDF plus logistic regression baseline, and measure it', 'A large model fine-tuned on a cluster', 'Nothing until you have a million labels', 'A rule list only'], 'A cheap baseline sets the bar and may be enough.'),
      type('The model will route 70% of 20,000 tickets automatically. How many minutes of routing work does that save at 2 minutes each?', ['28000', '28,000'], '14,000 tickets × 2 minutes.'),
      mc('The baseline reaches 78% accuracy. The confusion matrix shows billing and refunds are mixed up. Best next step?', ['Review the confused examples, clarify or merge the labels, and add examples', 'Ignore it', 'Double the epochs', 'Delete both queues'], 'Often the labels, not the model, are the problem.'),
      info('Confidence and a human in the loop', 'Do not route everything automatically. Route only tickets where the model’s confidence is above a **threshold**; send the rest to a person. Raising the threshold gives higher accuracy on the automatic part but automates fewer tickets.'),
      type('At a 0.9 threshold the model automatically routes 12,000 of the 20,000 tickets, with 97% accuracy on them. How many of those are routed wrongly?', ['360'], '12,000 × 3%.'),
      mc('How do you choose the threshold?', ['Weigh the cost of a mis-routed ticket against the cost of manual routing, using validation data', 'Always 0.5', 'Pick the highest value possible', 'Pick it at random'], 'It is a business trade-off.'),
      mc('A new product launches and customers use new words. What protects you?', ['Monitor accuracy and input drift, and retrain with agent corrections', 'Nothing is needed', 'Freeze the model forever', 'Remove the new words'], 'Language changes over time.'),
      order('Order the rollout', ['Label and clean the data', 'Train the baseline and review the errors', 'Set the confidence threshold from costs', 'Run in shadow mode and compare with agents', 'Go live for confident cases and keep humans for the rest'], 'Measure, calibrate, then automate.'),
      tf('Corrections that agents make to routed tickets provide free training labels.', true, 'This feedback loop improves the model over time.')),

    L('Interview drill: NLP and language models',
      info('Questions you will get', 'NLP interviews mix **fundamentals** (tokens, embeddings, TF-IDF), **modern practice** (LoRA, RAG, prompting) and **evaluation**. The follow-up is nearly always "how would you know it works?"'),
      match('Match the interview question to what it really tests', [['Why try TF-IDF before a transformer?', 'Baseline discipline'], ['How do you evaluate a summariser?', 'Metric limits and faithfulness'], ['What is LoRA?', 'Parameter-efficient adaptation'], ['How do you handle long documents?', 'Chunking and truncation trade-offs']]),
      type('LoRA adds two small matrices, 4096 × 8 and 8 × 4096, beside a 4096 × 4096 weight. How many trainable parameters is that?', ['65536', '65,536'], '4096 × 8 × 2. The full matrix has over 16 million.'),
      mc('Company knowledge changes every week. Do you fine-tune or use retrieval (RAG)?', ['Use retrieval for changing facts, and fine-tune for style or format', 'Always fine-tune weekly', 'Neither is possible', 'Retrain from scratch each week'], 'Facts belong in a store you can update.'),
      mc('"Precision or recall for a content-moderation filter?" A good answer…', ['Depends on the costs: missing harmful content versus blocking harmless content, then set the threshold accordingly', 'Always precision', 'Always recall', 'Neither matters'], 'Link the metric to a business cost.'),
      mc('Roughly how many tokens is a 1,000-word English text?', ['About 1,300', 'Exactly 1,000', 'About 100', 'About 10,000'], 'Sub-word tokenisation usually produces more tokens than words.'),
      info('Answer shape', 'Start with the simplest sensible approach, say how you would measure it, then explain when you would escalate. That sequence shows engineering judgement more than naming the biggest model.'),
      order('Order a strong answer to "How would you evaluate an LLM summariser in production?"', ['Define what good means: faithful, concise, covers the key points', 'Run cheap overlap metrics as a regression check', 'Review a sample for faithfulness with people or a judge model', 'Track results by slice and collect user feedback', 'Re-run the evaluation after every prompt or model change'], 'Definition, automation, review, slices, repetition.'),
      tf('Starting with the simplest baseline and escalating only when it fails is a good answer pattern.', true, 'It saves cost and gives you a comparison point.'))
  ]
};
